/// <reference path="./_shared/manga/manga-provider.d.ts" />
var LibGroup = class {
  constructor() {
    this.imgApiUrl = "https://api.cdnlibs.org";
    this.imgUrl = null;
  }
  getSettings() {
    return { supportsMultiScanlator: true };
  }
  async search(opts) {
    const url = new URL(`${this.apiUrl}/api/manga`);
    url.searchParams.set("page", "1");
    url.searchParams.append("site_id[]", String(this.siteId));
    if (opts.query) url.searchParams.set("q", opts.query);
    const json = await this.fetchJson(url.toString());
    if (!json) return [];
    return json.data.map((manga) => ({
      id: manga.slug_url,
      title: manga.rus_name || manga.name,
      synonyms: manga.rus_name && manga.name !== manga.rus_name ? [manga.name] : void 0,
      image: manga.cover.default ?? void 0
    }));
  }
  async findChapters(id) {
    const json = await this.fetchJson(`${this.apiUrl}/api/manga/${id}/chapters`);
    if (!json || json.data.length === 0) return [];
    const chapters = json.data.flatMap((chapter) => (chapter.branches.length > 0 ? chapter.branches : [null]).map((branch) => this.toChapterDetails(id, chapter, branch))).filter((chapter) => chapter !== null).sort((a, b) => this.chapterOrderValue(a.chapter) - this.chapterOrderValue(b.chapter));
    return chapters.map((chapter, index) => ({ ...chapter, index }));
  }
  async findChapterPages(id) {
    const json = await this.fetchJson(`${this.apiUrl}/api/manga/${id}`);
    if (!json) return [];
    const server = await this.getImgUrl();
    return json.data.pages.sort((a, b) => a.slug - b.slug).map((page, index) => ({
      url: `${server}${page.url}`,
      index,
      headers: { Referer: this.baseUrl }
    }));
  }
  chapterOrderValue(chapter) {
    const value = parseFloat(chapter);
    return Number.isNaN(value) ? Number.POSITIVE_INFINITY : value;
  }
