    return this.imgUrl ?? "";
  }
  async fetchJson(url) {
    try {
      const res = await fetch(url, {
        headers: {
          Accept: "application/json",
          Referer: this.baseUrl,
          "Site-Id": String(this.siteId)
        }
      });
      return res.ok ? await res.json() : null;
    } catch {
      return null;
    }
  }
};

